import {
	canonicalEndpointIdentity,
	expectedGet404Outcome,
	isHevyHttpError,
	NotFoundError,
} from "@hevy-mcp/hevy-client";

export type ExpectedReadError = "not_found" | "end_of_list";
export type ReadCollectionEndpoint = "/v1/routines" | "/v1/workouts";
export type ReadOperationError = Error | string;

/**
 * Classify only the documented read-side 404 cases.
 *
 * This function is deliberately pure. It does not inspect mutable client
 * state, perform I/O, or convert the error, so Effect programs can use it as
 * their error-channel boundary while Promise callers retain the original
 * error object.
 */
export function classifyReadError(
	error: ReadOperationError,
	endpoint: ReadCollectionEndpoint,
	page?: number,
): ExpectedReadError | undefined {
	const httpError = isHevyHttpError(error)
		? error
		: error instanceof NotFoundError
			? error
			: undefined;
	if (!httpError) return undefined;
	const canonical = canonicalEndpointIdentity(httpError.endpoint);
	if (canonical !== endpoint && !canonical.startsWith(`${endpoint}/`)) {
		return undefined;
	}

	const expected = expectedGet404Outcome(
		httpError.endpoint,
		httpError.method,
		httpError.status,
		page,
	);
	if (expected === "not_found") return "not_found";
	if (expected === "end_of_list") return "end_of_list";
	return undefined;
}

export function isExpectedReadNotFound(
	error: ReadOperationError,
	endpoint: ReadCollectionEndpoint,
): boolean {
	return classifyReadError(error, endpoint) === "not_found";
}

export function isExpectedReadEndOfList(
	error: ReadOperationError,
	endpoint: ReadCollectionEndpoint,
	page: number,
): boolean {
	return page > 1 && classifyReadError(error, endpoint, page) === "end_of_list";
}

import { describe, expect, it, vi } from "vitest";
import { Effect } from "effect";

import {
	createRoutinesGetOperation,
	createRoutinesListOperation,
} from "./routines.js";
import {
	createWorkoutsGetOperation,
	createWorkoutsListOperation,
} from "./workouts.js";

function assertCollapsedExecute(source: string): void {
	expect(source.match(/Effect\.runPromise/g)).toHaveLength(1);
	expect(source).not.toMatch(/Effect\.(tryPromise|promise)/);
	expect(source).toContain("Effect.catchIf");
}

describe("operations Effect collapse", () => {
	it("collapses workouts.get onto one Effect boundary", () => {
		const operation = createWorkoutsGetOperation({
			getWorkout: () => Effect.succeed({}),
		});

		assertCollapsedExecute(operation.execute.toString());
	});

	it("collapses workouts.list onto one Effect boundary", () => {
		const operation = createWorkoutsListOperation({
			getWorkouts: () => Effect.succeed({ workouts: [] }),
		});

		assertCollapsedExecute(operation.execute.toString());
	});

	it("collapses routines.get onto one Effect boundary", () => {
		const operation = createRoutinesGetOperation({
			getRoutineById: () => Effect.succeed({}),
		});

		assertCollapsedExecute(operation.execute.toString());
	});

	it("collapses routines.list onto one Effect boundary", () => {
		const operation = createRoutinesListOperation({
			getRoutines: () => Effect.succeed({ routines: [] }),
		});

		assertCollapsedExecute(operation.execute.toString());
	});

	it("passes an Effect-capable read seam directly into execute", async () => {
		const getWorkout = vi.fn(() => Effect.succeed({ id: "workout-1" }));
		const operation = createWorkoutsGetOperation({ getWorkout });

		await expect(
			operation.execute({ workoutId: "workout-1" }),
		).resolves.toEqual({
			workout: { id: "workout-1" },
		});

		const seamResult = getWorkout.mock.results[0]?.value;
		expect(seamResult).toBeDefined();
		await expect(Effect.runPromise(seamResult)).resolves.toEqual({
			id: "workout-1",
		});
	});
});

