import { describe, expect, it, vi } from "vitest";

import { createHevyClient } from "@hevy-mcp/hevy-client";
import { createOperations } from "./index.js";

type JsonValue = string | number | boolean | null | JsonObject | JsonValue[];
type JsonObject = { readonly [key: string]: JsonValue };

function response(data: JsonObject, status = 200): Response {
	return new Response(JSON.stringify(data), {
		status,
		headers: { "content-type": "application/json" },
	});
}

describe("createOperations public client injection", () => {
	it("[VAL-OPS-038] executes all workout and routine reads from createHevyClient", async () => {
		const fetchMock = vi.fn((input: RequestInfo | URL) => {
			const requestUrl =
				input instanceof Request
					? input.url
					: input instanceof URL
						? input.href
						: input;
			const url = new URL(requestUrl);

			switch (url.pathname) {
				case "/v1/workouts":
					return Promise.resolve(
						response({
							page: 1,
							page_count: 1,
							workouts: [{ id: "workout-1" }],
						}),
					);
				case "/v1/workouts/workout-1":
					return Promise.resolve(response({ id: "workout-1" }));
				case "/v1/routines":
					return Promise.resolve(
						response({
							page: 1,
							page_count: 1,
							routines: [{ id: "routine-1" }],
						}),
					);
				case "/v1/routines/routine-1":
					return Promise.resolve(response({ routine: { id: "routine-1" } }));
				default:
					return Promise.resolve(response({}, 404));
			}
		});
		const operations = createOperations(
			createHevyClient({
				apiKey: "test-key",
				baseUrl: "https://example.test",
				fetch: fetchMock,
				maxGetRetries: 0,
			}),
		);

		await expect(
			operations.workouts.list.execute({ page: 1, pageSize: 5 }),
		).resolves.toEqual({
			items: [{ id: "workout-1" }],
			page: 1,
			pageCount: 1,
		});
		await expect(
			operations.workouts.get.execute({ workoutId: "workout-1" }),
		).resolves.toEqual({
			workout: { id: "workout-1" },
		});
		await expect(
			operations.routines.list.execute({ page: 1, pageSize: 5 }),
		).resolves.toEqual({
			items: [{ id: "routine-1" }],
			page: 1,
			pageCount: 1,
		});
		await expect(
			operations.routines.get.execute({ routineId: "routine-1" }),
		).resolves.toEqual({
			routine: { id: "routine-1" },
		});

		expect(fetchMock).toHaveBeenCalledTimes(4);
	});

	it("rejects a Promise-only structural mock with a clear seam error", async () => {
		const client = {
			getWorkouts: vi.fn().mockResolvedValue({ workouts: [] }),
			getWorkout: vi.fn().mockResolvedValue({ id: "workout-1" }),
			getRoutines: vi.fn().mockResolvedValue({ routines: [] }),
			getRoutineById: vi.fn().mockResolvedValue({
				routine: { id: "routine-1" },
			}),
		};
		const operations = createOperations(client as never);

		await expect(
			operations.workouts.get.execute({ workoutId: "workout-1" }),
		).rejects.toThrow("internal request Effect seam");
	});

	it("rejects a malformed requestEffect property with the same clear error", async () => {
		const operations = createOperations({
			getWorkouts: vi.fn(),
			getWorkout: vi.fn(),
			getRoutines: vi.fn(),
			getRoutineById: vi.fn(),
			requestEffect: null,
		} as never);

		await expect(
			operations.workouts.get.execute({ workoutId: "workout-1" }),
		).rejects.toThrow("internal request Effect seam");
	});
});

import { HevyHttpError } from "@hevy-mcp/hevy-client";
import { describe, expect, it } from "vitest";
import {
	classifyReadError,
	isExpectedReadEndOfList,
	isExpectedReadNotFound,
} from "./operation-errors.js";

function notFound(endpoint: string, method = "GET") {
	return new HevyHttpError("not found", {
		status: 404,
		method,
		endpoint,
	});
}

describe("classifyReadError", () => {
	it("classifies a known resource 404", () => {
		const error = notFound("/v1/routines/routine-1");

		expect(classifyReadError(error, "/v1/routines")).toBe("not_found");
		expect(isExpectedReadNotFound(error, "/v1/routines")).toBe(true);
	});

	it("classifies a later collection-page 404", () => {
		const error = notFound("/v1/workouts");

		expect(classifyReadError(error, "/v1/workouts", 2)).toBe("end_of_list");
		expect(isExpectedReadEndOfList(error, "/v1/workouts", 2)).toBe(true);
	});

	it("does not hide first-page, mutation, or unrelated 404s", () => {
		expect(
			classifyReadError(notFound("/v1/workouts"), "/v1/workouts", 1),
		).toBeUndefined();
		expect(
			classifyReadError(notFound("/v1/workouts", "POST"), "/v1/workouts", 2),
		).toBeUndefined();
		expect(
			classifyReadError(notFound("/v1/routines/routine-1"), "/v1/workouts", 2),
		).toBeUndefined();
		expect(
			classifyReadError(new Error("network failure"), "/v1/workouts", 2),
		).toBeUndefined();
	});
});

import type { HevyClient, HevyExecutionOptions } from "@hevy-mcp/hevy-client";
import { HevyHttpError } from "@hevy-mcp/hevy-client";
import type {
	GetV1Workouts200,
	GetV1WorkoutsWorkoutid200,
} from "@hevy-mcp/hevy-client/types";
import { Effect } from "effect";
import { describe, expect, it } from "vitest";
import {
	createWorkoutsGetOperation,
	createWorkoutsListOperation,
	type WorkoutsGetAdapter,
	type WorkoutsListAdapter,
} from "./workouts.js";

interface InMemoryWorkoutsAdapter extends WorkoutsListAdapter {
	readonly requests: Array<{
		readonly params: Parameters<HevyClient["getWorkouts"]>[0];
		readonly options: Parameters<HevyClient["getWorkouts"]>[1];
	}>;
	readonly argumentCounts: number[];
}

function createInMemoryAdapter(
	responses: readonly (GetV1Workouts200 | Error)[],
): InMemoryWorkoutsAdapter {
	let responseIndex = 0;
	const requests: InMemoryWorkoutsAdapter["requests"] = [];
	const argumentCounts: InMemoryWorkoutsAdapter["argumentCounts"] = [];
	return {
		requests,
		argumentCounts,
		getWorkouts(params, options) {
			argumentCounts.push(arguments.length);
			requests.push({ params, options });
			const response = responses[responseIndex++] ?? { workouts: [] };
			if (response instanceof Error) return Effect.fail(response);
			return Effect.succeed(response);
		},
	};
}

function httpError(
	status: number,
	method: string,
	endpoint: string,
	message = "request failed",
) {
	return new HevyHttpError(message, {
		status,
		method,
		endpoint,
	});
}

function notFound(endpoint = "/v1/workouts", method = "GET") {
	return httpError(404, method, endpoint, "not found");
}

interface InMemoryWorkoutsGetAdapter extends WorkoutsGetAdapter {
	readonly requests: Array<{
		readonly workoutId: Parameters<HevyClient["getWorkout"]>[0];
		readonly options: Parameters<HevyClient["getWorkout"]>[1];
	}>;
	readonly argumentCounts: number[];
}

function abortable<T>(
	options: HevyExecutionOptions | undefined,
	error: Error,
): Effect.Effect<T, Error> {
	const signal = options?.signal;
	if (signal === undefined) return Effect.fail(error);
	return Effect.callback((resume) => {
		const rejectOnAbort = () => {
			signal.removeEventListener("abort", rejectOnAbort);
			const reason = signal.reason;
			resume(Effect.fail(reason instanceof Error ? reason : error));
		};
		if (signal.aborted) {
			rejectOnAbort();
		} else {
			signal.addEventListener("abort", rejectOnAbort, { once: true });
		}
		return Effect.sync(() =>
			signal.removeEventListener("abort", rejectOnAbort),
		);
	});
}

function createInMemoryGetAdapter(
	responses?:
		| GetV1WorkoutsWorkoutid200
		| Error
		| readonly (GetV1WorkoutsWorkoutid200 | Error | undefined)[],
): InMemoryWorkoutsGetAdapter {
	const requests: InMemoryWorkoutsGetAdapter["requests"] = [];
	const argumentCounts: InMemoryWorkoutsGetAdapter["argumentCounts"] = [];
	const responseSequence = Array.isArray(responses) ? responses : [responses];
	let responseIndex = 0;
	return {
		requests,
		argumentCounts,
		getWorkout(workoutId, options) {
			argumentCounts.push(arguments.length);
			requests.push({ workoutId, options });
			const response = responseSequence[responseIndex++];
			if (response instanceof Error) return Effect.fail(response);
			return Effect.succeed(response as GetV1WorkoutsWorkoutid200);
		},
	};
}

function createAbortAwareGetAdapter(error: Error): InMemoryWorkoutsGetAdapter {
	const requests: InMemoryWorkoutsGetAdapter["requests"] = [];
	const argumentCounts: InMemoryWorkoutsGetAdapter["argumentCounts"] = [];
	return {
		requests,
		argumentCounts,
		getWorkout(workoutId, options) {
			argumentCounts.push(arguments.length);
			requests.push({ workoutId, options });
			return abortable<GetV1WorkoutsWorkoutid200>(options, error);
		},
	};
}

function createAbortAwareListAdapter(error: Error): InMemoryWorkoutsAdapter {
	const requests: InMemoryWorkoutsAdapter["requests"] = [];
	const argumentCounts: InMemoryWorkoutsAdapter["argumentCounts"] = [];
	return {
		requests,
		argumentCounts,
		getWorkouts(params, options) {
			argumentCounts.push(arguments.length);
			requests.push({ params, options });
			return abortable<GetV1Workouts200>(options, error);
		},
	};
}

describe("workouts.get operation", () => {
	it("[VAL-OPS-001] succeeds with the workout entity and preserves the read descriptor", async () => {
		const adapter = createInMemoryGetAdapter({ id: "w1" });
		const operation = createWorkoutsGetOperation(adapter);
		const signal = new AbortController().signal;
		const options: HevyExecutionOptions = {
			signal,
			deadline: Date.now() + 5_000,
		};

		await expect(
